const raw = $input.first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

let message = '';
let actorRole = 'owner';
let actorPhone = '';
let actorEmail = '';
let memberId = null;

const waMsg = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (waMsg) {
  message = String(waMsg.text?.body || '').trim();
  actorPhone = String(waMsg.from || '').trim();
  actorRole = 'member';
} else if (body.from || body.sender_email || (body.subject && (body.text || body.body_text))) {
  const subject = String(body.subject || '').trim();
  const textBody = String(body.text || body.body_text || body.snippet || '').trim();
  message = [subject, textBody].filter(Boolean).join(': ');
  actorEmail = String(body.from || body.sender_email || body.email || '').trim().toLowerCase();
  actorRole = ['owner', 'staff', 'member', 'n8n_autopilot'].includes(body.actor_role)
    ? body.actor_role
    : 'member';
  memberId = body.member_id ? String(body.member_id).trim() : null;
} else {
  message = String(body.message || body.prompt || 'Run full gym autopilot').trim();
  actorRole = ['owner', 'staff', 'member', 'n8n_autopilot'].includes(body.actor_role)
    ? body.actor_role
    : 'owner';
  actorPhone = String(body.actor_phone || body.phone || '').trim();
  actorEmail = String(body.actor_email || body.email || '').trim().toLowerCase();
  memberId = body.member_id ? String(body.member_id).trim() : null;
}

if (!message) {
  message = 'Run full gym autopilot';
}

return [{
  json: {
    message,
    actor_role: actorRole,
    actor_phone: actorPhone,
    actor_email: actorEmail,
    member_id: memberId,
    sync_to_n8n: false,
  },
}];

const res = $input.first().json || {};
const req = $('Code - Normalize Inbound Agent Request').first().json;
const nowIST = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
}).format(new Date()) + ' IST';

if (res.error) {
  return [{
    json: {
      log_id: `AGT-ERR-${Date.now().toString(36).toUpperCase().slice(-5)}`,
      timestamp: nowIST,
      workflow: 'GM-05',
      member_id: req.member_id || 'STUDIO',
      action: 'AGENT_ERROR',
      status: 'FAILED',
      details: `Python AI backend unreachable: ${res.error.message || JSON.stringify(res.error)}`,
      reply: 'AI Gym Manager backend is currently unreachable. Please verify FASTAPI_PUBLIC_URL.',
    },
  }];
}

return [{
  json: {
    log_id: res.run_id || `AGT-${Date.now().toString(36).toUpperCase().slice(-6)}`,
    timestamp: res.timestamp_ist || nowIST,
    workflow: 'GM-05',
    member_id: req.member_id || 'STUDIO',
    action: res.intent || 'AGENT_RUN',
    status: 'COMPLETED',
    details: String(res.reply || '').slice(0, 450),
    reply: res.reply || 'Done.',
    tools_executed: res.tools_executed || [],
    google_sheets_sync: res.google_sheets_sync || {},
  },
}];
